#!/usr/bin/env bash
# Place and route one noc_tile and abstract it (issue #45):
#   klt synthesize -> klt place-and-route (to route) -> klt lef-abstract -> abutment check
# Writes:
#   layout/tile/requests/place-and-route.json   generated by gen_request.py (never hand-edited)
#   layout/tile/reports/place-and-route.json    klt envelope, host paths made repo-relative
#   layout/tile/reports/lef-abstract.json       klt envelope
#   layout/tile/out/noc_tile.gds, noc_tile.lef, out/SHA256SUMS   routed tile and its abstract
# One klt place-and-route unit, run serially; nothing here fans out. Takes about 2 h.
#
# Usage:  layout/tile/run.sh            run (resumes an interrupted P&R: klt place-and-route --resume)
#         layout/tile/run.sh --fresh    discard layout/tile/requests/.klt/place-and-route first
# Needs:  yosys, openroad on PATH at the versions in layout/tools.json; jq; python3;
#         klt: uvx at the pinned version if that resolves, else `klt` on PATH. The version
#         that ran is recorded in the envelope (provenance.klt_version).
#         The IHP-Open-PDK pinned in layout/pdk.json under $PDK_ROOT/ihp-sg13g2.
set -u

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
TILE="$ROOT/layout/tile"
REQ="$TILE/requests"
OUT="$TILE/out"
REP="$TILE/reports"
export PDK_ROOT="${PDK_ROOT:-$HOME/share/pdk}"
export PDK="$(jq -r .variant "$ROOT/layout/pdk.json")"
KLT_VER="$(jq -r .klayout_tools.version "$ROOT/layout/tools.json")"
if uvx --quiet --from "klayout-tools==$KLT_VER" klt --version >/dev/null 2>&1; then
  klt() { uvx --quiet --from "klayout-tools==$KLT_VER" klt "$@"; }
else
  echo "run.sh: klayout-tools==$KLT_VER does not resolve; using klt on PATH: $(command -v klt)" >&2
  klt() { command klt "$@"; }
fi
die() { echo "run.sh: $*" >&2; exit 2; }

fresh=0
case "${1:-}" in "") ;; --fresh) fresh=1 ;; *) die "usage: run.sh [--fresh]" ;; esac

check_pin() { case "$3" in "$2"*) ;; *) die "$1 mismatch: pinned '$2', found '$3' (worker-spec gap; do not install here)";; esac; }
check_pin yosys "$(jq -r .yosys.version_prefix "$ROOT/layout/tools.json")" "$(yosys -V 2>&1 | head -1)"
check_pin openroad "$(jq -r .openroad.version "$ROOT/layout/tools.json")" "$(openroad -version 2>&1 | head -1)"
stamp="$(klt pdk find --pdk "$PDK" 2>&1 | sed -n 's/^version: //p')"
check_pin pdk "$(jq -r .klt_pdk_version_stamp "$ROOT/layout/pdk.json")" "$stamp"

cd "$ROOT" || exit 2
mkdir -p "$OUT" "$REP"

# --- request (generated) ----------------------------------------------------
python3 -I "$TILE/gen_request.py" > "$REQ/place-and-route.json" || die "gen_request.py failed"

# --- netlist: re-synthesize (about 40 s) and require it to be the committed one
if [ "$fresh" = 1 ]; then rm -rf "$REQ/.klt/place-and-route"; fi
rm -rf "$REQ/.klt/synthesize"   # klt refuses a populated run dir; the netlist hash is checked below
klt synthesize "$REQ/synthesize.json" --format json > "$REQ/.synth.json" || { cat "$REQ/.synth.json" >&2; die "klt synthesize failed"; }
got="$(sha256sum "$REQ/.klt/synthesize/tile/noc_tile_synth.v" | cut -d' ' -f1)"
want="$(jq -r .netlist_sha256 "$REP/synthesize.json")"
rm -f "$REQ/.synth.json"
[ "$got" = "${want#sha256:}" ] || die "netlist sha256 $got != committed reports/synthesize.json $want (RTL changed: re-run klt synthesize and commit its report first)"

# --- place and route (one unit, serial, resumable) --------------------------
resume=""; [ -d "$REQ/.klt/place-and-route" ] && resume="--resume"
klt place-and-route $resume "$REQ/place-and-route.json" --format json > "$REP/place-and-route.json" 2> "$REP/place-and-route.err"
rc=$?
[ -s "$REP/place-and-route.json" ] || cp "$REP/place-and-route.err" "$REP/place-and-route.json"
rm -f "$REP/place-and-route.err"
python3 -I "$ROOT/layout/smoke/sanitize.py" "$ROOT" "$PDK_ROOT" "$REP/place-and-route.json"
[ $rc -eq 0 ] || die "klt place-and-route failed (exit $rc); envelope kept at layout/tile/reports/place-and-route.json"

GDS="$REQ/.klt/place-and-route/noc_tile.gds"
[ -s "$GDS" ] || die "no routed GDS at $GDS"
cp "$GDS" "$OUT/noc_tile.gds"

# --- abstract ---------------------------------------------------------------
die_um="$(jq -r '.floorplan.die_area_um[2]' "$REQ/place-and-route.json")"
sock="$(mktemp)"; trap 'rm -f "$sock"' EXIT
python3 -I "$TILE/gen_socket.py" "$REP/place-and-route.json" "$die_um" > "$sock" || die "gen_socket.py failed"
klt lef-abstract "$OUT/noc_tile.gds" --socket "$sock" --macro-name noc_tile --top noc_tile \
    --cell-library sg13g2_stdcell --require-power-pins --obs-mode coarse \
    -o "$OUT/noc_tile.lef" --format json > "$REP/lef-abstract.json" || { cat "$REP/lef-abstract.json" >&2; die "klt lef-abstract failed"; }
python3 -I "$ROOT/layout/smoke/sanitize.py" "$ROOT" "$PDK_ROOT" "$REP/lef-abstract.json"
( cd "$OUT" && sha256sum noc_tile.gds noc_tile.lef > SHA256SUMS )

python3 -I "$TILE/check_abut.py" "$REP/place-and-route.json" || die "link pins do not line up for abutment"

echo "== summary"
jq -r '"place-and-route: \(.status) stage=\(.stage_reached) route_drc=\(.route_drc_violation_count) util_pct=\(.utilization_pct) klt=\(.provenance.klt_version)"' "$REP/place-and-route.json"
jq -r '"lef-abstract: pins=\(.pin_count) obs=\(.obs_shape_count) power_pins=\(.power_pins.status)"' "$REP/lef-abstract.json"
cat "$OUT/SHA256SUMS"
